# Define revised full-rectangle stamping, compute from g

def trans2(grid):
 h,w=len(grid),len(grid[0]); bg=max(set(v for row in grid for v in row),key=lambda x:sum(row.count(x) for row in grid))
 pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg,5)]
 r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
 templ=[row[c0:c1+1] for row in grid[r0:r1+1]]
 out=[row[:] for row in grid]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==5:
    top=r-(r1-r0)//2; left=c-(c1-c0)//2
    for i in range(len(templ)):
     for j in range(len(templ[0])):
      rr=top+i;cc=left+j
      if 0<=rr<h and 0<=cc<w: out[rr][cc]=templ[i][j]
 return out
